        Assert.True(dispenser.Dispense(Of(0, 0, 4)));

        Step(machine, dispenser, new(100, 0), new Operation.Withdraw(20),
            new AtmResult(AtmStatus.CannotDispense, default, 0, new(100, 0)), Of(0, 0, 1));
    }

