namespace Atm.Tests;
public class ZzTmp
{
    [Fact]
    public void Show()
    {
        var d = new MoneyDispenser(new NoteCounts(5, 0, 0));
        var a = new CashMachine(d); var b = new CashMachine(d);
        b.Execute(new(100, 0), new Operation.Withdraw(50));
        var r1 = a.Execute(new(0, 0), new Operation.Deposit(new NoteCounts(1, 0, 0)));
        var d2 = new MoneyDispenser(new NoteCounts(0, 4, 0));
